20.8 Ranking / Recommendation / Retrieval Metrics
Search engines, recommenders and retrieval systems don’t output a single label — they output an ordered list, and what matters is whether the relevant items sit near the top.

Precision@k / Recall@k — of the top k results, how many are relevant / how many of all relevant items did we surface.
Average Precision (AP) and its mean over queries, MAP — reward putting relevant items early.
DCG / NDCG — discounted cumulative gain, normalized to [0,1]; handles graded relevance and position discounting.
MRR — mean reciprocal rank of the first relevant hit (great for “one right answer” tasks).
Hit rate@k — did at least one relevant item make the top k.



Code
# "For dummies" explanation versions of each metric:

# Of the top k items that the system recommended, how many were actually relevant?
precision_at_k &lt;- function(recommended, relevant, k) {
  topk &lt;- recommended[1:k]
  sum(topk %in% relevant) / k
}

# Of all the relevant (correct) items possible, how many did we manage to show in the first k
# recommendations?
recall_at_k &lt;- function(recommended, relevant, k) {
  if (length(relevant) == 0) return(0.0)
  topk &lt;- recommended[1:k]
  sum(topk %in% relevant) / length(relevant)
}

# Measures how well we put relevant items early in our ranked list.
# For every relevant item, it checks: when you saw it, what was the precision up to that point?
# Then it averages those values, rewarding lists with good stuff near the top.
average_precision &lt;- function(recommended, relevant) {
  if (length(relevant) == 0) return(0.0)
  hits &lt;- 0; score &lt;- 0.0
  for (i in seq_along(recommended)) {
    if (recommended[i] %in% relevant) {
      hits &lt;- hits + 1
      score &lt;- score + hits / i  # Precision at this spot in the list
    }
  }
  score / length(relevant)
}

# The 'average of averages'. For a batch of searches/users, take each one's average_precision,
# then average those numbers.
mean_average_precision &lt;- function(list_of_recommended, list_of_relevant) {
  aps &lt;- mapply(average_precision, list_of_recommended, list_of_relevant)
  if (length(aps) &gt; 0) mean(aps) else 0.0
}

# Discounted Cumulative Gain: Gives credit for relevant items near the top, but less credit as
# you go down. 'relevance' = a named list: bigger numbers mean more relevant.
dcg_at_k &lt;- function(recommended, relevance, k) {
  total &lt;- 0.0
  n &lt;- min(k, length(recommended))
  for (i in seq_len(n)) {
    item &lt;- recommended[i]
    score &lt;- if (item %in% names(relevance)) relevance[[item]] else 0
    total &lt;- total + score / log2(i + 1)
  }
  total
}

# Normalized DCG: Same as DCG, but we divide by the best possible score.
# So you get a value between 0 and 1: 1 means you put all the most important stuff at the very top.
ndcg_at_k &lt;- function(recommended, relevance, k) {
  dcg &lt;- dcg_at_k(recommended, relevance, k)
  ideal &lt;- sort(unlist(relevance), decreasing = TRUE)[1:min(k, length(relevance))]
  idcg &lt;- sum(sapply(seq_along(ideal), function(i) ideal[i] / log2(i + 1)))
  if (idcg != 0) dcg / idcg else 0.0
}

# Look at each search/user: where was their first relevant item? If it was first, you get 1
# point; second, 1/2; third, 1/3, etc. Then average across all users.
mean_reciprocal_rank &lt;- function(list_of_recommended, list_of_relevant) {
  total &lt;- 0.0
  for (i in seq_along(list_of_recommended)) {
    rec &lt;- list_of_recommended[[i]]; rel_set &lt;- list_of_relevant[[i]]
    rr &lt;- 0.0
    for (j in seq_along(rec)) {
      if (rec[j] %in% rel_set) { rr &lt;- 1 / j; break }  # Found first hit at rank i
    }
    total &lt;- total + rr
  }
  total / length(list_of_recommended)
}

# For each user/query: did they see at least one relevant item in the top k? (Yes=1, No=0)
hit_rate_at_k &lt;- function(list_of_recommended, list_of_relevant, k) {
  hits &lt;- 0
  for (i in seq_along(list_of_recommended)) {
    rec &lt;- list_of_recommended[[i]]; rel_set &lt;- list_of_relevant[[i]]
    if (any(rec[1:min(k, length(rec))] %in% rel_set)) hits &lt;- hits + 1
  }
  hits / length(list_of_recommended)
}

# Demos with simple explanations

# Let's say our system recommends these 5 docs, in this order:
recs &lt;- c("d1", "d2", "d3", "d4", "d5")
# And the user thinks d1, d3, and d5 are the relevant ones.
rel &lt;- c("d1", "d3", "d5")

cat(sprintf("Precision@3: %.3f  # Of top 3, what fraction is relevant?\n", precision_at_k(recs, rel, 3)))
cat(sprintf("Recall@3   : %.3f     # Of all relevant docs, how many are in top 3?\n", recall_at_k(recs, rel, 3)))
cat(sprintf("AP         : %.3f  # Did we rank relevant docs early?\n", average_precision(recs, rel)))
graded &lt;- list(d1 = 3, d2 = 0, d3 = 2, d4 = 0, d5 = 1)
cat(sprintf("NDCG@5     : %.3f     # Did we put the highest-importance docs at the very top?\n", ndcg_at_k(recs, graded, 5)))

# Example with multiple users/queries:
R_ &lt;- list(c("a", "b", "c"), c("x", "y", "z"))
RL_ &lt;- list(c("b"), c("x", "z"))  # What each user actually wanted
cat(sprintf("MAP        : %.3f  # Are relevant items near the top, averaged over users?\n", mean_average_precision(R_, RL_)))
cat(sprintf("MRR        : %.3f     # How quickly do we return a first relevant doc, on average?\n", mean_reciprocal_rank(R_, RL_)))
cat(sprintf("HitRate@2  : %.3f         # For each user, did at least 1 relevant show up in top 2?\n", hit_rate_at_k(R_, RL_, 2)))

8.3 Base Decision Tree (Classification + Regression)
A shared tree that handles both tasks, controlled by the task parameter.


Code
# This is a super simple decision tree.
# It can work for both:
# - Classification (choose the most common class)
# - Regression (predict the average value)
# Just set the 'task' argument to either 'classification' or 'regression'.
#
# Tree nodes are plain R lists: list(feat=, thr=, left=, right=). A leaf is just a bare
# value (not a list) — mirrors the Python version's `dict` internal node / bare-value leaf.

DecisionTree &lt;- setRefClass(
  "DecisionTree",
  fields = list(max_depth = "numeric", min_samples_split = "numeric", max_features = "ANY",
                task = "character", seed = "ANY", tree = "ANY"),
  methods = list(
    initialize = function(max_depth = 5, min_samples_split = 2, max_features = NULL,
                           task = "classification", seed = 0, ...) {
      max_depth &lt;&lt;- max_depth               # How deep can the tree go?
      min_samples_split &lt;&lt;- min_samples_split  # Minimum samples to split a node
      max_features &lt;&lt;- max_features         # How many features to consider at a split (NULL = all)
      task &lt;&lt;- task                         # 'classification' or 'regression'
      seed &lt;&lt;- seed                         # Random seed for reproducibility
      tree &lt;&lt;- NULL
      callSuper(...)
    },

    impurity_fn = function(y) if (task == "classification") gini(y) else mse(y),
    leaf_value  = function(y) if (task == "classification") mode_val(y) else mean_val(y),

    best_split = function(X, y) {
      # Try EVERY possible split for EVERY (candidate) feature. Pick the best.
      n &lt;- nrow(X); n_feats &lt;- ncol(X)
      imp_parent &lt;- impurity_fn(y)

      if (!is.null(max_features) && max_features &lt; n_feats) {
        feat_ids &lt;- sample(seq_len(n_feats), max_features)   # random subset (Random Forest style)
      } else {
        feat_ids &lt;- seq_len(n_feats)
      }

      best &lt;- list(gain = -1, feat = NULL, thr = NULL)
      for (feat in feat_ids) {
        vals &lt;- sort(unique(X[, feat]))
        if (length(vals) &lt; 2) next
        thresholds &lt;- (vals[-length(vals)] + vals[-1]) / 2
        for (thr in thresholds) {
          left_mask &lt;- X[, feat] &lt;= thr
          yl &lt;- y[left_mask]; yr &lt;- y[!left_mask]
          if (length(yl) == 0 || length(yr) == 0) next
          gain &lt;- imp_parent - (length(yl) / n) * impurity_fn(yl) - (length(yr) / n) * impurity_fn(yr)
          if (gain &gt; best$gain) best &lt;- list(gain = gain, feat = feat, thr = thr)
        }
      }
      best
    },

    build = function(X, y, depth) {
      # Stop growing if: all y same, too few samples, or max depth reached.
      if (length(unique(y)) == 1 || length(y) &lt; min_samples_split || depth &gt;= max_depth) {
        return(leaf_value(y))
      }
      split &lt;- best_split(X, y)
      if (is.null(split$feat)) return(leaf_value(y))

      f &lt;- split$feat; thr &lt;- split$thr
      left_mask &lt;- X[, f] &lt;= thr
      list(feat = f, thr = thr,
           left  = build(X[left_mask, , drop = FALSE],  y[left_mask],  depth + 1),
           right = build(X[!left_mask, , drop = FALSE], y[!left_mask], depth + 1))
    },

    fit = function(X, y) {
      if (!is.null(seed)) set.seed(seed)
      tree &lt;&lt;- build(X, y, 0)
      invisible(.self)
    },

    traverse_one = function(x, node) {
      if (!is.list(node)) return(node)   # a bare value = leaf
      branch &lt;- if (x[node$feat] &lt;= node$thr) node$left else node$right
      traverse_one(x, branch)
    },

    predict = function(X) sapply(seq_len(nrow(X)), function(i) traverse_one(X[i, ], tree)),
    predict_one = function(x) traverse_one(x, tree)
  )
)

8.5 Random Forest
Random Forest is a powerful machine learning ensemble method that combines the predictions of many decision trees to improve accuracy and robustness.

It works by creating many decision trees using bootstrapped samples of the training data.
Each tree makes predictions independently, and the forest combines their outputs (using majority vote for classification or averaging for regression).
At each split, only a random subset of features is considered, which makes the trees more diverse and less correlated.

This approach reduces overfitting compared to a single decision tree and achieves better performance in most cases.

Theory
Steps to build a Random Forest (with equations and explanations):

Bagging (Bootstrap Aggregating):

For each of the \(B\) trees you want in your forest:

Draw a bootstrap sample from your data (random sample with replacement).
Mathematically: For dataset \(D\) of size \(n\), create \(D_b\) by sampling \(n\) times from \(D\) with replacement.


Feature Subspacing at Each Split:

When each tree tries to split at a node, instead of searching over all \(p\) features, it can only look at a random subset of \(m\) features (\(m &lt; p\)).
Equation: \(m = \sqrt{p}\) (for classification), \(m = p/3\) (for regression), where \(p\) = number of features.
For example, if you have \(p\) features, then at each split:

Randomly choose \(m\) features from the \(p\) possible.
Find the best split among these \(m\) features.

Summary Table:

\(m = \sqrt{p}\) (classification)
\(m = p/3\) (regression)


Tree Growth:

Grow each tree to its full depth (or up to a max depth you specify), using only the \(m\) random features at each split.

Prediction:

For classification: Each tree votes on the class, and the class with the most votes wins (majority voting).

Predict label \(\hat{y} = \mathrm{mode}(\{\hat{y}^{(b)}\}_{b=1}^B)\)

For regression: Average all tree predictions.

Predict value \(\hat{y} = \frac{1}{B} \sum_{b=1}^{B} \hat{y}^{(b)}\)



Why does Random Forest work? - If all trees used all features, they would be similar—especially if some features are much more “powerful” than others. - By forcing each split to consider only a random selection of features, the trees become diverse. - When you average (regression) or vote (classification) these diverse trees, the overall forest prediction has lower variance and usually higher accuracy!


8.5.1 Random Forest Classifier


Code
# A Random Forest is an ensemble of decision trees, where each tree is trained on a bootstrap
# sample (random sampling with replacement) from the original data, and at each split only a
# random subset of features is considered.

RandomForestClassifier &lt;- setRefClass(
  "RandomForestClassifier",
  fields = list(n_estimators = "numeric", max_depth = "numeric", max_features = "ANY",
                min_samples_split = "numeric", seed = "numeric", trees = "list"),
  methods = list(
    initialize = function(n_estimators = 10, max_depth = 5, max_features = "sqrt",
                           min_samples_split = 2, seed = 0, ...) {
      n_estimators &lt;&lt;- n_estimators; max_depth &lt;&lt;- max_depth; max_features &lt;&lt;- max_features
      min_samples_split &lt;&lt;- min_samples_split; seed &lt;&lt;- seed; trees &lt;&lt;- list()
      callSuper(...)
    },

    n_features_for = function(p) {
      # Determine number of features to sample at each split.
      if (identical(max_features, "sqrt")) max(1, as.integer(sqrt(p)))
      else if (identical(max_features, "log2")) max(1, as.integer(log2(p)))
      else if (is.numeric(max_features)) min(max_features, p)
      else p   # use all features
    },

    fit = function(X, y) {
      trees &lt;&lt;- list()
      p &lt;- ncol(X)
      m &lt;- n_features_for(p)
      for (b in 0:(n_estimators - 1)) {
        bs &lt;- bootstrap_sample(X, y, seed = seed + b)
        tree &lt;- DecisionTree$new(max_depth = max_depth, min_samples_split = min_samples_split,
                                  max_features = m, task = "classification", seed = seed + b)
        tree$fit(bs$X, bs$y)
        trees[[b + 1]] &lt;&lt;- tree
      }
      invisible(.self)
    },

    predict = function(X) {
      all_preds &lt;- lapply(trees, function(t) t$predict(X))
      sapply(seq_len(nrow(X)), function(i) mode_val(sapply(all_preds, function(p) p[i])))
    },

    predict_proba = function(X) {
      all_preds &lt;- lapply(trees, function(t) t$predict(X))
      classes &lt;- sort(unique(unlist(all_preds)))
      lapply(seq_len(nrow(X)), function(i) {
        votes &lt;- sapply(all_preds, function(p) p[i])
        tbl &lt;- table(factor(votes, levels = classes))
        setNames(as.numeric(tbl) / n_estimators, classes)
      })
    },

    feature_importances = function(n_features) {
      # Estimate feature importance as mean decrease in Gini impurity across all splits.
      # NOTE: faithfully mirrors the Python original, where tree nodes never actually
      # store a 'gain' value — so this always returns all zeros (a quirk of the source).
      importances &lt;- rep(0.0, n_features)
      traverse_imp &lt;- function(node) {
        if (!is.list(node)) return(invisible(NULL))
        importances[node$feat + 1] &lt;&lt;- importances[node$feat + 1] + 0
        traverse_imp(node$left)
        traverse_imp(node$right)
      }
      for (tree in trees) traverse_imp(tree$tree)
      total &lt;- sum(importances)
      if (total &gt; 0) importances / total else rep(0.0, n_features)
    }
  )
)




8.5.2 Random Forest Regressor


Code
# Random Forest for regression. Splits on MSE reduction; aggregates by averaging.

RandomForestRegressor &lt;- setRefClass(
  "RandomForestRegressor",
  fields = list(n_estimators = "numeric", max_depth = "numeric", max_features = "ANY",
                min_samples_split = "numeric", seed = "numeric", trees = "list"),
  methods = list(
    initialize = function(n_estimators = 10, max_depth = 5, max_features = "third",
                           min_samples_split = 2, seed = 0, ...) {
      n_estimators &lt;&lt;- n_estimators; max_depth &lt;&lt;- max_depth; max_features &lt;&lt;- max_features
      min_samples_split &lt;&lt;- min_samples_split; seed &lt;&lt;- seed; trees &lt;&lt;- list()
      callSuper(...)
    },

    n_features_for = function(p) {
      if (identical(max_features, "sqrt")) max(1, as.integer(sqrt(p)))
      else if (identical(max_features, "third")) max(1, p %/% 3)
      else if (identical(max_features, "log2")) max(1, as.integer(log2(p)))
      else if (is.numeric(max_features)) min(max_features, p)
      else p
    },

    fit = function(X, y) {
      trees &lt;&lt;- list()
      p &lt;- ncol(X)
      m &lt;- n_features_for(p)
      for (b in 0:(n_estimators - 1)) {
        bs &lt;- bootstrap_sample(X, y, seed = seed + b)
        tree &lt;- DecisionTree$new(max_depth = max_depth, min_samples_split = min_samples_split,
                                  max_features = m, task = "regression", seed = seed + b)
        tree$fit(bs$X, bs$y)
        trees[[b + 1]] &lt;&lt;- tree
      }
      invisible(.self)
    },

    predict = function(X) {
      all_preds &lt;- lapply(trees, function(t) t$predict(X))
      sapply(seq_len(nrow(X)), function(i) mean_val(sapply(all_preds, function(p) p[i])))
    }
  )
)

8.6 Extra Trees (Extremely Randomized Trees)

Theory
Extra Trees (Geurts et al., 2006) push randomisation further than Random Forest:




Random Forest
Extra Trees




Bootstrap
Yes
No (full dataset)


Feature subset per split
Yes \((\sqrt{p})\)
Yes \((\sqrt{p})\)


Threshold search
Best among candidates
Completely random



Because thresholds are drawn at random (no search), Extra Trees trains much faster and introduces more variance-reducing randomisation, often matching or beating Random Forest.
\[\text{threshold} \sim \text{Uniform}(\min_i x_{ij},\ \max_i x_{ij}) \quad \text{for each candidate feature } j\]


8.6.1 Extra Trees Classifier


Code
# Extremely Randomized Trees for classification.
# No bootstrap resampling; random thresholds for each split; trains very fast.

ExtraTreesClassifier &lt;- setRefClass(
  "ExtraTreesClassifier",
  fields = list(n_estimators = "numeric", max_depth = "numeric", max_features = "ANY",
                min_samples_split = "numeric", seed = "numeric", trees = "list"),
  methods = list(
    initialize = function(n_estimators = 10, max_depth = 5, max_features = "sqrt",
                           min_samples_split = 2, seed = 0, ...) {
      n_estimators &lt;&lt;- n_estimators; max_depth &lt;&lt;- max_depth; max_features &lt;&lt;- max_features
      min_samples_split &lt;&lt;- min_samples_split; seed &lt;&lt;- seed; trees &lt;&lt;- list()
      callSuper(...)
    },

    n_features_for = function(p) {
      if (identical(max_features, "sqrt")) max(1, as.integer(sqrt(p))) else p
    },

    build_extra = function(X, y, depth, m) {
      # Stops splitting if all labels are the same, too small, or reached max depth.
      if (length(unique(y)) == 1 || length(y) &lt; min_samples_split || depth &gt;= max_depth) {
        return(mode_val(y))
      }

      n &lt;- nrow(X); p &lt;- ncol(X)
      feat_ids &lt;- sample(seq_len(p), min(m, p))   # m random features for this split
      best &lt;- list(gain = -1, feat = NULL, thr = NULL)
      imp_parent &lt;- gini(y)

      for (feat in feat_ids) {
        vals &lt;- X[, feat]
        lo &lt;- min(vals); hi &lt;- max(vals)
        if (lo == hi) next                        # no split possible on this feature
        thr &lt;- runif(1, lo, hi)                    # RANDOM threshold, not the best one
        left_mask &lt;- X[, feat] &lt;= thr
        yl &lt;- y[left_mask]; yr &lt;- y[!left_mask]
        if (length(yl) == 0 || length(yr) == 0) next
        gain &lt;- imp_parent - (length(yl) / n) * gini(yl) - (length(yr) / n) * gini(yr)
        if (gain &gt; best$gain) best &lt;- list(gain = gain, feat = feat, thr = thr)
      }

      if (is.null(best$feat)) return(mode_val(y))

      f &lt;- best$feat; thr &lt;- best$thr
      left_mask &lt;- X[, f] &lt;= thr
      list(feat = f, thr = thr,
           left  = build_extra(X[left_mask, , drop = FALSE],  y[left_mask],  depth + 1, m),
           right = build_extra(X[!left_mask, , drop = FALSE], y[!left_mask], depth + 1, m))
    },

    traverse_one = function(x, node) {
      if (!is.list(node)) return(node)
      branch &lt;- if (x[node$feat] &lt;= node$thr) node$left else node$right
      traverse_one(x, branch)
    },

    fit = function(X, y) {
      p &lt;- ncol(X)
      m &lt;- n_features_for(p)
      trees &lt;&lt;- list()
      for (b in 0:(n_estimators - 1)) {
        set.seed(seed + b)   # each tree gets its own randomness
        trees[[b + 1]] &lt;&lt;- build_extra(X, y, 0, m)
      }
      invisible(.self)
    },

    predict = function(X) {
      all_preds &lt;- lapply(trees, function(tr) sapply(seq_len(nrow(X)), function(i) traverse_one(X[i, ], tr)))
      sapply(seq_len(nrow(X)), function(i) mode_val(sapply(all_preds, function(p) p[i])))
    }
  )
)




8.6.2 Extra Trees Regressor


Code
# Imagine you want to predict a number, like the price of a house. Instead of making one big
# decision, this model builds several "random" decision trees and averages their answers to
# get a better prediction. The randomness helps prevent overthinking / memorizing too much.

ExtraTreesRegressor &lt;- setRefClass(
  "ExtraTreesRegressor",
  fields = list(n_estimators = "numeric", max_depth = "numeric", max_features = "ANY",
                min_samples_split = "numeric", seed = "numeric", trees = "list"),
  methods = list(
    initialize = function(n_estimators = 10, max_depth = 5, max_features = "sqrt",
                           min_samples_split = 2, seed = 0, ...) {
      n_estimators &lt;&lt;- n_estimators; max_depth &lt;&lt;- max_depth; max_features &lt;&lt;- max_features
      min_samples_split &lt;&lt;- min_samples_split; seed &lt;&lt;- seed; trees &lt;&lt;- list()
      callSuper(...)
    },

    n_features_for = function(p) {
      if (identical(max_features, "sqrt")) max(1, as.integer(sqrt(p))) else max(1, p %/% 3)
    },

    build_extra = function(X, y, depth, m) {
      if (length(y) &lt; min_samples_split || depth &gt;= max_depth) return(mean_val(y))

      n &lt;- nrow(X); p &lt;- ncol(X)
      feat_ids &lt;- sample(seq_len(p), min(m, p))
      best &lt;- list(gain = -1, feat = NULL, thr = NULL)
      imp_parent &lt;- mse(y)

      for (feat in feat_ids) {
        vals &lt;- X[, feat]
        lo &lt;- min(vals); hi &lt;- max(vals)
        if (lo == hi) next
        thr &lt;- runif(1, lo, hi)
        left_mask &lt;- X[, feat] &lt;= thr
        yl &lt;- y[left_mask]; yr &lt;- y[!left_mask]
        if (length(yl) == 0 || length(yr) == 0) next
        gain &lt;- imp_parent - (length(yl) / n) * mse(yl) - (length(yr) / n) * mse(yr)
        if (gain &gt; best$gain) best &lt;- list(gain = gain, feat = feat, thr = thr)
      }

      if (is.null(best$feat)) return(mean_val(y))

      f &lt;- best$feat; thr &lt;- best$thr
      left_mask &lt;- X[, f] &lt;= thr
      list(feat = f, thr = thr,
           left  = build_extra(X[left_mask, , drop = FALSE],  y[left_mask],  depth + 1, m),
           right = build_extra(X[!left_mask, , drop = FALSE], y[!left_mask], depth + 1, m))
    },

    traverse_one = function(x, node) {
      if (!is.list(node)) return(node)
      branch &lt;- if (x[node$feat] &lt;= node$thr) node$left else node$right
      traverse_one(x, branch)
    },

    fit = function(X, y) {
      p &lt;- ncol(X)
      m &lt;- n_features_for(p)
      trees &lt;&lt;- list()
      for (b in 0:(n_estimators - 1)) {
        set.seed(seed + b)
        trees[[b + 1]] &lt;&lt;- build_extra(X, y, 0, m)
      }
      invisible(.self)
    },

    predict = function(X) {
      all_preds &lt;- lapply(trees, function(tr) sapply(seq_len(nrow(X)), function(i) traverse_one(X[i, ], tr)))
      sapply(seq_len(nrow(X)), function(i) mean_val(sapply(all_preds, function(p) p[i])))
    }
  )
)

