function BuildTree(X, y, depth):
    if stopping_condition_met:
        return Leaf(majority_class(y))

    best_feature, best_threshold = find_best_split(X, y)
    left_X, left_y   = samples where x[feature] ≤ threshold
    right_X, right_y = samples where x[feature] &gt;  threshold

    return Node(
        feature    = best_feature,
        threshold  = best_threshold,
        left       = BuildTree(left_X, left_y, depth+1),
        right      = BuildTree(right_X, right_y, depth+1)
    )
Stopping conditions: - Maximum depth reached - Minimum samples to split (&lt; min_samples_split) - Node is already pure

6.4 From-Scratch R Implementation


Code
# decision_tree.R

# ── EASY DECISION TREE CODE: EXPLAINED FOR BEGINNERS ──
#
# WHAT IS IMPURITY?
# Impurity just means "how mixed up" the data is at a decision tree node.
# - If all labels are the same (e.g. all apples or all oranges), impurity is zero (very "pure").
# - If it's a jumble (e.g. half apples, half oranges), impurity is high.

gini &lt;- function(y) {
  # Gini impurity for a vector of labels y.
  # Think: "How likely are you to pick two RANDOM samples of DIFFERENT class?"
  # Returns 0 if all are the same, 0.5 if two classes are perfectly mixed.
  n &lt;- length(y)
  if (n == 0) return(0.0)
  counts &lt;- table(y)
  1.0 - sum((counts / n)^2)   # (More mixed = closer to 0.5)
}

entropy &lt;- function(y) {
  # Entropy: Another way to measure "messiness"/"uncertainty".
  # Returns 0 if all identical. Higher is more mixed. Uses logarithms.
  n &lt;- length(y)
  if (n == 0) return(0.0)
  counts &lt;- table(y)
  p &lt;- counts / n
  p &lt;- p[p &gt; 0]
  -sum(p * log2(p))
}

information_gain &lt;- function(y, y_left, y_right, criterion = "gini") {
  # How much better does a split make things?
  # Info gain = impurity BEFORE split - (weighted impurity AFTER split)
  impurity_fn &lt;- if (criterion == "gini") gini else entropy
  n &lt;- length(y); n_l &lt;- length(y_left); n_r &lt;- length(y_right)
  impurity_fn(y) - (n_l / n) * impurity_fn(y_left) - (n_r / n) * impurity_fn(y_right)
}

# ── TREE STRUCTURE (Node) ──
# Represents a spot in the tree ("node").
#   - Internal nodes decide where to split.
#   - Leaf nodes make the actual prediction.
# Fields:
#   feature_idx: which feature to look at?
#   threshold:   value to split at (e.g. is x &gt;= 2.5?)
#   left/right:  children nodes, or NULL if leaf
#   is_leaf:     TRUE/FALSE
#   prediction:  prediction to make if at a leaf (most common class, or average value)
#   n_samples:   how many samples at this node
Node &lt;- setRefClass(
  "Node",
  fields = list(feature_idx = "ANY", threshold = "ANY", left = "ANY", right = "ANY",
                is_leaf = "logical", prediction = "ANY", impurity = "numeric", n_samples = "numeric"),
  methods = list(
    initialize = function(...) {
      feature_idx &lt;&lt;- NULL; threshold &lt;&lt;- NULL; left &lt;&lt;- NULL; right &lt;&lt;- NULL
      is_leaf &lt;&lt;- FALSE; prediction &lt;&lt;- NULL; impurity &lt;&lt;- 0.0; n_samples &lt;&lt;- 0
      callSuper(...)
    }
  )
)

# ── HELPER FUNCTIONS ──

accuracy_score &lt;- function(y_true, y_pred) mean(y_true == y_pred)   # What percent did we get right?
mse_score &lt;- function(y_true, y_pred) mean((y_true - y_pred)^2)     # Average squared difference (regression)

majority_class &lt;- function(y) {
  # Most frequent label, preserving y's original type (numeric or character).
  tbl &lt;- table(y)
  best &lt;- names(tbl)[which.max(tbl)]
  if (is.numeric(y)) as.numeric(best) else best
}

gather_leaf_indices &lt;- function(node, part_idxs, X) {
  # Map validation samples down to whichever leaf they land on, starting from
  # the tree's root — mirrors the from-scratch Python helper exactly.
  if (node$is_leaf) return(part_idxs)
  left_part  &lt;- part_idxs[X[part_idxs, node$feature_idx] &lt;= node$threshold]
  right_part &lt;- part_idxs[X[part_idxs, node$feature_idx] &gt;  node$threshold]
  res &lt;- integer(0)
  if (!is.null(node$left))  res &lt;- c(res, gather_leaf_indices(node$left, left_part, X))
  if (!is.null(node$right)) res &lt;- c(res, gather_leaf_indices(node$right, right_part, X))
  res
}

# ── DECISION TREE CLASSIFIER (for categories) ──
# Uses a tree to separate data (apples vs oranges, etc).
# Key parts:
#   $fit()        : Train the tree.
#   $predict()    : Predict labels for new data.
#   $print_tree() : Show the tree as text.
#   $prune()      : Shrink the tree to avoid "memorizing" (overfitting).

DecisionTreeClassifier &lt;- setRefClass(
  "DecisionTreeClassifier",
  fields = list(max_depth = "ANY", min_samples_split = "numeric",
                min_samples_leaf = "numeric", criterion = "character",
                root = "ANY", n_features = "ANY"),
  methods = list(
    initialize = function(max_depth = NULL, min_samples_split = 2,
                           min_samples_leaf = 1, criterion = "gini", ...) {
      max_depth &lt;&lt;- max_depth                       # Don't grow beyond this depth (NULL = no limit)
      min_samples_split &lt;&lt;- min_samples_split        # Don't split if too few samples here
      min_samples_leaf &lt;&lt;- min_samples_leaf          # Each leaf needs at least this many samples
      criterion &lt;&lt;- criterion                        # Which impurity? ('gini' or 'entropy')
      root &lt;&lt;- NULL; n_features &lt;&lt;- NULL
      callSuper(...)
    },

    best_split = function(X, y) {
      # Try EVERY possible split for EVERY feature. Pick the best ("least messy").
      best_gain &lt;- -Inf; best_feature &lt;- NULL; best_threshold &lt;- NULL
      for (feature_idx in seq_len(ncol(X))) {
        values &lt;- sort(unique(X[, feature_idx]))
        if (length(values) &lt; 2) next
        thresholds &lt;- (values[-length(values)] + values[-1]) / 2   # midpoint between adjacent values
        for (threshold in thresholds) {
          left_mask &lt;- X[, feature_idx] &lt;= threshold
          y_left &lt;- y[left_mask]; y_right &lt;- y[!left_mask]
          if (length(y_left) &lt; min_samples_leaf || length(y_right) &lt; min_samples_leaf) next
          gain &lt;- information_gain(y, y_left, y_right, criterion)
          if (gain &gt; best_gain) {
            best_gain &lt;- gain; best_feature &lt;- feature_idx; best_threshold &lt;- threshold
          }
        }
      }
      list(feature = best_feature, threshold = best_threshold, gain = best_gain)
    },

    build_tree = function(X, y, depth) {
      # Build tree recursively (splits further and further until can't anymore).
      # Base cases (stop growing): all same label, too few samples, or max depth reached.
      node &lt;- Node$new()
      node$n_samples &lt;- length(y)
      node$prediction &lt;- majority_class(y)

      if (length(unique(y)) == 1 ||
          length(y) &lt; min_samples_split ||
          (!is.null(max_depth) && depth &gt;= max_depth)) {
        node$is_leaf &lt;- TRUE
        return(node)
      }

      split &lt;- best_split(X, y)
      if (is.null(split$feature)) {
        node$is_leaf &lt;- TRUE
        return(node)
      }

      left_mask &lt;- X[, split$feature] &lt;= split$threshold
      node$feature_idx &lt;- split$feature
      node$threshold &lt;- split$threshold
      node$left  &lt;- build_tree(X[left_mask, , drop = FALSE],  y[left_mask],  depth + 1)
      node$right &lt;- build_tree(X[!left_mask, , drop = FALSE], y[!left_mask], depth + 1)

      node
    },

    fit = function(X, y) {
      # Grow the tree using your feature data X and target labels y.
      n_features &lt;&lt;- ncol(X)
      root &lt;&lt;- build_tree(X, y, depth = 0)
      invisible(.self)
    },

    traverse_one = function(x, node) {
      # For a single data point x, walk down the tree to predict.
      if (node$is_leaf) return(node$prediction)
      if (x[node$feature_idx] &lt;= node$threshold) traverse_one(x, node$left) else traverse_one(x, node$right)
    },

    predict = function(X) {
      # Predict labels for a whole batch of samples.
      sapply(seq_len(nrow(X)), function(i) traverse_one(X[i, ], root))
    },

    print_tree = function(node = NULL, depth = 0, feature_names = NULL) {
      # Print the tree as text, visualizing each split and showing each leaf prediction.
      if (is.null(node)) node &lt;- root
      indent &lt;- strrep("    ", depth)
      if (node$is_leaf) {
        cat(sprintf("%s-&gt; Predict: %s  (n=%d)\n", indent, node$prediction, node$n_samples))
      } else {
        fname &lt;- if (!is.null(feature_names)) feature_names[node$feature_idx] else sprintf("x[%d]", node$feature_idx)
        cat(sprintf("%sIf %s &lt;= %.3f:\n", indent, fname, node$threshold))
        print_tree(node$left, depth + 1, feature_names)
        cat(sprintf("%sElse:\n", indent))
        print_tree(node$right, depth + 1, feature_names)
      }
    },

    # ── PRUNING ──
    prune = function(X_val, y_val, metric = "accuracy") {
      # Prune the tree to avoid "memorizing" (overfitting), bottom-up:
      # if collapsing a split into one leaf does not make validation score
      # worse, keep it collapsed; otherwise restore the split.
      prune_node &lt;- function(node) {
        if (node$is_leaf) return(invisible(NULL))

        if (!is.null(node$left))  prune_node(node$left)
        if (!is.null(node$right)) prune_node(node$right)

        # Only consider pruning if both children are leaves (so we can "collapse" them)
        if (!(!is.null(node$left) && !is.null(node$right) && node$left$is_leaf && node$right$is_leaf)) {
          return(invisible(NULL))
        }

        backup_left &lt;- node$left; backup_right &lt;- node$right
        was_leaf &lt;- node$is_leaf
        node$left &lt;- NULL; node$right &lt;- NULL
        node$is_leaf &lt;- TRUE

        idxs &lt;- gather_leaf_indices(root, seq_len(nrow(X_val)), X_val)
        y_sub &lt;- y_val[idxs]
        if (length(y_sub) &gt; 0) node$prediction &lt;- majority_class(y_sub)

        y_pred_pruned &lt;- predict(X_val)
        pruned_score &lt;- if (metric == "accuracy") accuracy_score(y_val, y_pred_pruned) else
          stop("Unknown scoring metric for classification.")

        # Hold on, let's compare to original
        node$left &lt;- backup_left; node$right &lt;- backup_right
        node$is_leaf &lt;- was_leaf
        y_pred_orig &lt;- predict(X_val)
        orig_score &lt;- accuracy_score(y_val, y_pred_orig)

        # If pruning did NOT hurt accuracy, keep pruned; otherwise, restore
        if (pruned_score &gt;= orig_score) {
          node$left &lt;- NULL; node$right &lt;- NULL
          node$is_leaf &lt;- TRUE
          if (length(y_sub) &gt; 0) node$prediction &lt;- majority_class(y_sub)
        }
      }
      prune_node(root)
      invisible(.self)
    }
  )
)

# ── DECISION TREE REGRESSOR (for predicting numbers) ──

mse_impurity &lt;- function(y) {
  # For regression, we want numbers in a group to be as close as possible.
  # MSE impurity is "average squared difference from average": lower is better!
  if (length(y) == 0) return(0.0)
  m &lt;- mean(y)
  mean((y - m)^2)
}

DecisionTreeRegressor &lt;- setRefClass(
  "DecisionTreeRegressor",
  fields = list(max_depth = "ANY", min_samples_split = "numeric",
                min_samples_leaf = "numeric", root = "ANY"),
  methods = list(
    initialize = function(max_depth = NULL, min_samples_split = 2, min_samples_leaf = 1, ...) {
      max_depth &lt;&lt;- max_depth
      min_samples_split &lt;&lt;- min_samples_split
      min_samples_leaf &lt;&lt;- min_samples_leaf
      root &lt;&lt;- NULL
      callSuper(...)
    },

    best_split = function(X, y) {
      # Try all splits: which division makes numbers in each group closest together?
      best_reduction &lt;- -Inf; best_feature &lt;- NULL; best_threshold &lt;- NULL
      parent_mse &lt;- mse_impurity(y)
      n &lt;- length(y)
      for (feat in seq_len(ncol(X))) {
        values &lt;- sort(unique(X[, feat]))
        if (length(values) &lt; 2) next
        thresholds &lt;- (values[-length(values)] + values[-1]) / 2
        for (thr in thresholds) {
          left_mask &lt;- X[, feat] &lt;= thr
          yl &lt;- y[left_mask]; yr &lt;- y[!left_mask]
          if (length(yl) &lt; min_samples_leaf || length(yr) &lt; min_samples_leaf) next
          reduction &lt;- parent_mse - (length(yl) / n) * mse_impurity(yl) - (length(yr) / n) * mse_impurity(yr)
          if (reduction &gt; best_reduction) {
            best_reduction &lt;- reduction; best_feature &lt;- feat; best_threshold &lt;- thr
          }
        }
      }
      list(feature = best_feature, threshold = best_threshold)
    },

    build = function(X, y, depth) {
      # Build regression tree recursively. If we can't split, leaf = mean value of this group.
      node &lt;- Node$new()
      node$n_samples &lt;- length(y)
      node$prediction &lt;- mean(y)
      if (length(y) &lt; min_samples_split || (!is.null(max_depth) && depth &gt;= max_depth)) {
        node$is_leaf &lt;- TRUE
        return(node)
      }
      split &lt;- best_split(X, y)
      if (is.null(split$feature)) {
        node$is_leaf &lt;- TRUE
        return(node)
      }
      left_mask &lt;- X[, split$feature] &lt;= split$threshold
      node$feature_idx &lt;- split$feature; node$threshold &lt;- split$threshold
      node$left  &lt;- build(X[left_mask, , drop = FALSE],  y[left_mask],  depth + 1)
      node$right &lt;- build(X[!left_mask, , drop = FALSE], y[!left_mask], depth + 1)
      node
    },

    fit = function(X, y) {
      # Fit the tree using your feature data X and labels y (numbers).
      root &lt;&lt;- build(X, y, 0)
      invisible(.self)
    },

    traverse_one = function(x, node) {
      # For a single data point x, walk down the tree until a leaf. Predict mean for that leaf.
      if (node$is_leaf) return(node$prediction)
      traverse_one(x, if (x[node$feature_idx] &lt;= node$threshold) node$left else node$right)
    },

    predict = function(X) {
      # Predict all values for batch of samples.
      vapply(seq_len(nrow(X)), function(i) traverse_one(X[i, ], root), numeric(1))
    },

    # ── PRUNING FOR REGRESSION TREE ──
    prune = function(X_val, y_val, metric = "mse") {
      # Prune this regression tree to simplify it, but only if validation error (MSE) doesn't get worse!
      prune_node &lt;- function(node) {
        if (node$is_leaf) return(invisible(NULL))

        if (!is.null(node$left))  prune_node(node$left)
        if (!is.null(node$right)) prune_node(node$right)

        if (!(!is.null(node$left) && !is.null(node$right) && node$left$is_leaf && node$right$is_leaf)) {
          return(invisible(NULL))
        }

        backup_left &lt;- node$left; backup_right &lt;- node$right
        was_leaf &lt;- node$is_leaf
        node$left &lt;- NULL; node$right &lt;- NULL
        node$is_leaf &lt;- TRUE

        # Prediction = average of true y's landing here
        idxs &lt;- gather_leaf_indices(root, seq_len(nrow(X_val)), X_val)
        y_sub &lt;- y_val[idxs]
        if (length(y_sub) &gt; 0) node$prediction &lt;- mean(y_sub)

        # Evaluate before/after pruning using MSE
        y_pred_pruned &lt;- predict(X_val)
        pruned_score &lt;- if (metric == "mse") mse_score(y_val, y_pred_pruned) else
          stop("Unknown metric for regression pruning.")

        node$left &lt;- backup_left; node$right &lt;- backup_right
        node$is_leaf &lt;- was_leaf
        y_pred_orig &lt;- predict(X_val)
        orig_score &lt;- mse_score(y_val, y_pred_orig)

        # If merging (pruning) helped or had no effect, keep it
        if (pruned_score &lt;= orig_score) {
          node$left &lt;- NULL; node$right &lt;- NULL
          node$is_leaf &lt;- TRUE
          if (length(y_sub) &gt; 0) node$prediction &lt;- mean(y_sub)
        }
      }
      prune_node(root)
      invisible(.self)
    }
  )
)

