# naive_bayes.R

GaussianNaiveBayes &lt;- setRefClass(
  "GaussianNaiveBayes",
  fields = list(var_smoothing = "numeric", class_priors = "list",
                means = "list", variances = "list", classes = "ANY"),
  methods = list(
    initialize = function(var_smoothing = 1e-9, ...) {
      var_smoothing &lt;&lt;- var_smoothing
      class_priors &lt;&lt;- list(); means &lt;&lt;- list(); variances &lt;&lt;- list(); classes &lt;&lt;- c()
      callSuper(...)
    },

    fit = function(X, y) {
      n &lt;- nrow(X)
      classes &lt;&lt;- sort(unique(y))
      for (c in classes) {
        key &lt;- as.character(c)
        X_c &lt;- X[y == c, , drop = FALSE]   # Samples belonging to class c
        n_c &lt;- nrow(X_c)

        class_priors[[key]] &lt;&lt;- log(n_c / n)    # Prior: P(y=c)

        mu &lt;- colMeans(X_c)                                            # Per-feature mean
        va &lt;- colSums(sweep(X_c, 2, mu, "-")^2) / n_c + var_smoothing  # Per-feature variance
        means[[key]]     &lt;&lt;- mu
        variances[[key]] &lt;&lt;- va
      }
      invisible(.self)
    },

    log_gaussian = function(x, mu, var_) {
      # Log probability density of x under N(mu, var).
      -0.5 * log(2 * pi * var_) - (x - mu)^2 / (2 * var_)
    },

    log_likelihood = function(x, c) {
      # Sum of log P(xj | y=c) over all features j.
      key &lt;- as.character(c)
      sum(log_gaussian(x, means[[key]], variances[[key]]))
    },

    predict_log_proba = function(X) {
      # Return log posterior for each class for each sample.
      lapply(seq_len(nrow(X)), function(i) {
        x &lt;- X[i, ]
        sapply(classes, function(c) class_priors[[as.character(c)]] + log_likelihood(x, c))
      })
    },

    predict = function(X) {
      log_probs &lt;- predict_log_proba(X)
      sapply(log_probs, function(lp) classes[which.max(lp)])
    }
  )
)


# ── Multinomial Naive Bayes (for text) ─────────────────────────────────────

MultinomialNaiveBayes &lt;- setRefClass(
  "MultinomialNaiveBayes",
  fields = list(alpha = "numeric", class_priors = "list",
                feature_log_probs = "list", classes = "ANY"),
  methods = list(
    initialize = function(alpha = 1.0, ...) {
      alpha &lt;&lt;- alpha   # Laplace smoothing parameter
      class_priors &lt;&lt;- list(); feature_log_probs &lt;&lt;- list(); classes &lt;&lt;- c()
      callSuper(...)
    },

    fit = function(X, y) {
      # X: matrix of feature count vectors (rows = documents). y: class labels.
      n &lt;- nrow(X)
      n_features &lt;- ncol(X)
      classes &lt;&lt;- sort(unique(y))

      for (c in classes) {
        key &lt;- as.character(c)
        X_c &lt;- X[y == c, , drop = FALSE]
        class_priors[[key]] &lt;&lt;- log(nrow(X_c) / n)

        # Total count of each feature in class c
        feature_counts &lt;- colSums(X_c)
        total_count &lt;- sum(feature_counts) + alpha * n_features

        feature_log_probs[[key]] &lt;&lt;- log((feature_counts + alpha) / total_count)
      }
      invisible(.self)
    },

    predict = function(X) {
      sapply(seq_len(nrow(X)), function(i) {
        xi &lt;- X[i, ]
        scores &lt;- sapply(classes, function(c) {
          key &lt;- as.character(c)
          class_priors[[key]] + sum(xi * feature_log_probs[[key]])
        })
        classes[which.max(scores)]
      })
    }
  )
)


# ── Simple Text Vectorizer ───────────────────────────────────────────────────

BagOfWords &lt;- setRefClass(
  "BagOfWords",
  fields = list(vocab = "list"),
  methods = list(
    initialize = function(...) { vocab &lt;&lt;- list(); callSuper(...) },

    fit = function(documents) {
      words &lt;- sort(unique(unlist(strsplit(tolower(documents), "\\s+"))))
      vocab &lt;&lt;- setNames(as.list(seq_along(words)), words)
      invisible(.self)
    },

    transform = function(documents) {
      n_vocab &lt;- length(vocab)
      vocab_names &lt;- names(vocab)
      mat &lt;- t(vapply(documents, function(doc) {
        vec &lt;- rep(0L, n_vocab)
        toks &lt;- strsplit(tolower(doc), "\\s+")[[1]]
        for (word in toks) {
          idx &lt;- match(word, vocab_names)
          if (!is.na(idx)) vec[idx] &lt;- vec[idx] + 1L
        }
        vec
      }, integer(n_vocab)))
      rownames(mat) &lt;- NULL
      mat
    },

    fit_transform = function(documents) { fit(documents); transform(documents) }
  )
)


