# svm.R

polynomial_kernel &lt;- function(x, y, c = 1, d = 2) {
  # Polynomial kernel: (x^T y + c)^d
  (sum(x * y) + c)^d
}

rbf_kernel &lt;- function(x, y, gamma = 1.0) {
  # RBF (Gaussian) kernel: exp(-gamma * ||x-y||^2)
  squared_dist &lt;- sum((x - y)^2)
  exp(-gamma * squared_dist)
}

sigmoid_kernel &lt;- function(x, y, kappa = 0.01, c = 0.0) {
  # Sigmoid kernel: tanh(kappa * x^T y + c)
  tanh(kappa * sum(x * y) + c)
}

# This is a simple implementation of a Linear Support Vector Machine (SVM) using
# Stochastic Gradient Descent (SGD) in plain base R. It's written for clarity, not
# for speed or production use, and doesn't use any modeling libraries!
# The goal: find a line (or hyperplane) that separates two classes with the biggest "gap" (margin).
#
# The training tries to minimize:
#   Loss = (How wrong the predictions are) + (how big/complex the weights are)
#   Specifically: C * average hinge loss + (1/2) * sum of squared weights
#   Here C controls how much you care about classification mistakes vs. keeping weights small.

LinearSVM &lt;- setRefClass(
  "LinearSVM",
  fields = list(Cparam = "numeric", lr = "numeric", n_iter = "numeric", w = "numeric", b = "numeric"),
  methods = list(
    # NOTE: the constructor argument and field are named `Cparam`, not `C` — a
    # RefClass field/argument literally named `C` collides with R's `methods::new()`
    # (partial argument matching against its `Class` parameter), so we avoid it.
    initialize = function(Cparam = 1.0, learning_rate = 0.001, n_iterations = 1000, ...) {
      # Cparam: regularization parameter (tradeoff between margin and mistakes).
      # learning_rate: how big are weight updates each step.
      # n_iterations: how many full passes over data.
      Cparam &lt;&lt;- Cparam; lr &lt;&lt;- learning_rate; n_iter &lt;&lt;- n_iterations
      w &lt;&lt;- numeric(0); b &lt;&lt;- 0.0
      callSuper(...)
    },

    hinge_loss = function(X, y) {
      # Compute average hinge loss + regularization on all data points.
      total &lt;- 0.0
      for (i in seq_len(nrow(X))) {
        margin &lt;- y[i] * (sum(w * X[i, ]) + b)
        total &lt;- total + max(0.0, 1.0 - margin)
      }
      Cparam * total / length(y) + 0.5 * sum(w^2)
    },

    fit = function(X, y) {
      # Learn weights to separate classes using SGD. y: labels (1 or -1).
      n &lt;- nrow(X); p &lt;- ncol(X)
      w &lt;&lt;- rep(0.0, p)
      b &lt;&lt;- 0.0

      for (iter in seq_len(n_iter)) {
        indices &lt;- sample(seq_len(n))   # Shuffle the training data indices (SGD)

        for (i in indices) {
          xi &lt;- X[i, ]; yi &lt;- y[i]
          z &lt;- sum(w * xi) + b
          margin &lt;- yi * z

          if (margin &gt;= 1) {
            w &lt;&lt;- w - lr * w   # Far enough from the boundary: just shrink weights (regularization)
          } else {
            # Either wrong side or inside margin: push in right direction and regularize
            w &lt;&lt;- w - lr * (w - Cparam * yi * xi)
            b &lt;&lt;- b + lr * Cparam * yi   # Update bias too
          }
        }
      }
      invisible(.self)
    },

    decision_function = function(X) {
      # For each sample in X, compute the score (w^T x + b).
      as.numeric(X %*% w) + b
    },

    predict = function(X) {
      # &gt;=0 goes to 1, otherwise -1.
      ifelse(decision_function(X) &gt;= 0, 1, -1)
    }
  )
)


# Kernel SVM using dual hinge-loss SGD.
# Decision function: f(x) = b + sum_i alpha_i * y_i * K(x_i, x)

KernelSVM &lt;- setRefClass(
  "KernelSVM",
  fields = list(kernel = "character", kernel_params = "list", Cparam = "numeric", lr = "numeric",
                n_iter = "numeric", X_train = "ANY", y_train = "ANY", alpha = "numeric", b = "numeric"),
  methods = list(
    # (see note above LinearSVM — avoid a field/argument literally named `C`)
    initialize = function(kernel = "linear", Cparam = 1.0, learning_rate = 0.01,
                           n_iterations = 2000, kernel_params = list(), ...) {
      kernel &lt;&lt;- kernel; kernel_params &lt;&lt;- kernel_params
      Cparam &lt;&lt;- Cparam; lr &lt;&lt;- learning_rate; n_iter &lt;&lt;- n_iterations
      X_train &lt;&lt;- NULL; y_train &lt;&lt;- NULL; alpha &lt;&lt;- numeric(0); b &lt;&lt;- 0.0
      callSuper(...)
    },

    K = function(x, z) {
      if (kernel == "linear") {
        sum(x * z)
      } else if (kernel == "polynomial") {
        polynomial_kernel(x, z, kernel_params$c %||% 1, kernel_params$d %||% 2)
      } else if (kernel == "rbf") {
        rbf_kernel(x, z, kernel_params$gamma %||% 1.0)
      } else if (kernel == "sigmoid") {
        sigmoid_kernel(x, z, kernel_params$kappa %||% 0.01, kernel_params$c %||% 0.0)
      } else {
        stop(sprintf("Unknown kernel: %s", kernel))
      }
    },

    score_one = function(x) {
      b + sum(vapply(seq_len(nrow(X_train)),
                      function(i) alpha[i] * y_train[i] * K(X_train[i, ], x), numeric(1)))
    },

    fit = function(X, y) {
      n &lt;- nrow(X)
      X_train &lt;&lt;- X; y_train &lt;&lt;- y
      alpha &lt;&lt;- rep(0.0, n)
      b &lt;&lt;- 0.0

      for (iter in seq_len(n_iter)) {
        indices &lt;- sample(seq_len(n))
        for (i in indices) {
          margin &lt;- y[i] * score_one(X[i, ])
          if (margin &lt; 1) {
            alpha[i] &lt;&lt;- alpha[i] + lr * Cparam
            b &lt;&lt;- b + lr * Cparam * y[i]
          }
          alpha &lt;&lt;- alpha * (1 - lr * 0.001)
        }
      }
      invisible(.self)
    },

    predict = function(X) {
      vapply(seq_len(nrow(X)), function(i) if (score_one(X[i, ]) &gt;= 0) 1 else -1, numeric(1))
    }
  )
)

# small helper: `a %||% b` returns a unless it's NULL, then returns b
`%||%` &lt;- function(a, b) if (is.null(a)) b else a

accuracy &lt;- function(y_true, y_pred) mean(y_true == y_pred)


